"""
Tests for ~/.aws/config editing (multi_aws_tool.aws.profile_config)
"""

from multi_aws_tool.aws import profile_config as pc

CONFIG = """\
# my aws config
[default]
region = eu-west-1

[sso-session acme]
sso_start_url = https://acme.awsapps.com/start
sso_region = eu-west-1

# Generated by MultiAWSTool - ReadOnly profiles
[profile mat-Prod-ReadOnly]
sso_session = acme
sso_account_id = 111111111111
sso_role_name = ReadOnly
region = eu-west-1

# hand written
[profile prod-ro]
sso_session = acme
sso_account_id = 111111111111
sso_role_name = ReadOnly
"""


def test_parse_lists_profiles_and_sessions():
    assert set(pc.list_profiles(CONFIG)) == {"default", "mat-Prod-ReadOnly", "prod-ro"}
    assert pc.list_sso_sessions(CONFIG)["acme"]["sso_start_url"] == "https://acme.awsapps.com/start"
    assert pc.list_profiles(CONFIG)["mat-Prod-ReadOnly"]["sso_account_id"] == "111111111111"


def test_render_roundtrip_is_lossless():
    preamble, sections = pc.parse(CONFIG)
    assert pc._render(preamble, sections) == CONFIG


def test_upsert_updates_in_place_and_appends_new():
    text, created, updated = pc.upsert_sections(CONFIG, {
        "profile mat-Prod-ReadOnly": pc.profile_values("acme", "111111111111", "ReadOnly", "us-east-1"),
        "profile mat-Dev-ReadOnly": pc.profile_values("acme", "222222222222", "ReadOnly", "eu-west-1"),
    }, comment="Generated by test")
    assert created == ["profile mat-Dev-ReadOnly"]
    assert updated == ["profile mat-Prod-ReadOnly"]
    assert pc.list_profiles(text)["mat-Prod-ReadOnly"]["region"] == "us-east-1"
    # the comment that belongs to the next section is preserved, in order
    assert text.index("region = us-east-1") < text.index("# hand written") < text.index("[profile prod-ro]")
    assert text.startswith("# my aws config\n")
    assert text.rstrip().endswith("region = eu-west-1")
    assert "# Generated by test\n[profile mat-Dev-ReadOnly]" in text
    assert text.count("[profile mat-Prod-ReadOnly]") == 1


def test_upsert_into_empty_file():
    text, created, _ = pc.upsert_sections("", {"sso-session x": {"sso_region": "eu-west-1"}})
    assert text == "[sso-session x]\nsso_region = eu-west-1\n"
    assert created == ["sso-session x"]


def test_find_and_remove_duplicates_keeps_prefixed():
    groups = pc.find_duplicate_profiles(CONFIG, prefix="mat")
    assert len(groups) == 1
    assert groups[0].keep == "mat-Prod-ReadOnly"
    assert groups[0].remove == ["prod-ro"]

    text = pc.remove_sections(CONFIG, pc.all_remove_indexes(groups))
    assert "prod-ro" not in text
    assert "[profile mat-Prod-ReadOnly]" in text
    assert "[default]" in text


def test_prefix_only_ignores_unprefixed():
    assert pc.find_duplicate_profiles(CONFIG, prefix="mat", prefix_only=True) == []


def test_same_name_duplicates_removed_by_position():
    text = CONFIG + "\n[profile mat-Prod-ReadOnly]\nsso_session = acme\nsso_account_id = 111111111111\nsso_role_name = ReadOnly\n"
    groups = pc.find_duplicate_profiles(text, prefix="mat", prefix_only=True)
    assert groups[0].remove == ["mat-Prod-ReadOnly"]
    cleaned = pc.remove_sections(text, pc.all_remove_indexes(groups))
    assert cleaned.count("[profile mat-Prod-ReadOnly]") == 1


def test_write_config_keeps_backup(tmp_path):
    path = tmp_path / "config"
    assert pc.write_config("a\n", path) is None
    backup = pc.write_config("b\n", path)
    assert backup.read_text() == "a\n"
    assert path.read_text() == "b\n"


def test_aws_config_file_env(monkeypatch, tmp_path):
    monkeypatch.setenv("AWS_CONFIG_FILE", str(tmp_path / "cfg"))
    assert pc.aws_config_path() == tmp_path / "cfg"
